-- verify after 11 (SELECT only)
-- generated by scripts/prod-open/sat-expand-sql.ts (SAT_11=1 or SAT_24=1). Run: npx supabase db query --linked -f <this file>. Idempotent; drafts only (never published here); published sets/attempts untouched.

select s.name, s.version_no, s.status, s.readiness_status, (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id) as items,
  (select count(*) from mock_exam_set_items i join problems p on p.id = i.problem_id where i.exam_set_id = s.id and i.problem_id = any (array['4cc47e7c-e766-47d8-aa9b-ae16aeb96d71','9977438d-6d27-48ed-aebb-c4ad8e08c6c0','f59b7f57-b596-4235-9902-d8036d9040ff']::uuid[]) and p.published_version_id = i.problem_version_id) as manual_items_on_new_version,
  (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id and i.problem_id = any (array['4cc47e7c-e766-47d8-aa9b-ae16aeb96d71','9977438d-6d27-48ed-aebb-c4ad8e08c6c0','f59b7f57-b596-4235-9902-d8036d9040ff']::uuid[])) as manual_items
from mock_exam_sets s where s.status = 'draft' and s.archived_at is null and s.name = any (array['SAT Practice Test 1','SAT Practice Test 3','SAT Practice Test 21']) order by length(s.name), s.name;
select count(*) as published_sets_unchanged from mock_exam_sets where status = 'published' and archived_at is null;
